require "rails_helper"

RSpec.describe Timekeeping::LocalOwner do
  # "A stale body generation on any of the five operations gives 409 stale_generation and writes nothing, including a retry whose earlier answer is stored"
  # "The generation check comes before replay, so a stale generation always gets 409 and changes nothing."
  it "local owner answers a stale-generation retry of a stored prepare and commit with stale_generation and changes no row" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    old_generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 60.0, note: "", bill_status: "unbilled"
    )
    actor = described_class::Actor.service(
      name: "invoice-boundary", company_id: company.id,
      operations: %w[reservations.prepare reservations.commit reservations.abort invoices.mark_billed agents.detach_entries]
    )
    operation_id = SecureRandom.uuid
    prepare_body = { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active", "entries" => [entry.id] }
    commit_body = { "invoice_id" => 501, "operation_id" => operation_id }
    call = lambda do |operation, body, generation|
      described_class.call(operation:, company_id: company.id, generation: generation.to_s, actor:,
                           params: { "body" => body.merge("generation" => generation) })
    end
    expect(call.call(:prepare, prepare_body, old_generation).status).to eq(200)
    expect(call.call(:commit, commit_body, old_generation).status).to eq(200)
    snapshot = lambda do
      %w[reservations invoice_operations service_idempotency_receipts entry_audits entry_outbox_items entries].index_with do |table|
        ActiveRecord::Base.connection.select_all("SELECT * FROM #{table} ORDER BY 1, 2").to_a
      end
    end
    TimekeepingOwnership.current.update!(generation: old_generation + 1)
    before = snapshot.call

    stale_prepare = call.call(:prepare, prepare_body, old_generation)
    stale_commit = call.call(:commit, commit_body, old_generation)

    expect([stale_prepare.status, stale_prepare.body]).to eq([409, { "reason" => "stale_generation" }])
    expect([stale_commit.status, stale_commit.body]).to eq([409, { "reason" => "stale_generation" }])
    expect(snapshot.call).to eq(before)
  end
end

