      Timekeeping::LocalEntry.create!(company_id: owner.id, user_id: create(:user).id, project_id: project.id,
                                      work_date: Date.current, duration: 60.0, note: "", bill_status: "unbilled")
    end
    callers = [
      [company, "invoice-boundary", 501],
      [company, "invoice-cleanup", 502],
      [other_company, "invoice-boundary", 501]
    ]

    answers = callers.map do |owner, name, invoice_id|
      actor = described_class::Actor.service(name:, company_id: owner.id, operations:)
      entry = make_entry.call(owner)
      [:prepare, :commit].map do |operation|
        body = { "invoice_id" => invoice_id, "operation_id" => operation_id, "generation" => generation }
        body = body.merge("disposition" => "active", "entries" => [entry.id]) if operation == :prepare
