  it "local abort unlocks only the entry whose last reservation it removed" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    held, fresh = Array.new(2) do
      Timekeeping::LocalEntry.create!(
        company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
        duration: 60.0, note: "", bill_status: "unbilled"
      )
    end
    actor = described_class::Actor.service(
      name: "invoice-boundary", company_id: company.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
    )
    call = lambda do |operation, body|
      described_class.call(operation:, company_id: company.id, generation:, actor:,
                           params: { "body" => { "generation" => generation }.merge(body) })
    end
    first = SecureRandom.uuid
    call.call(:prepare, "invoice_id" => 501, "operation_id" => first, "disposition" => "active", "entries" => [held.id])
    call.call(:commit, "invoice_id" => 501, "operation_id" => first)
    second = SecureRandom.uuid
    expect(call.call(:prepare, "invoice_id" => 501, "operation_id" => second, "disposition" => "active",
                               "entries" => [held.id, fresh.id]).status).to eq(200)
    held_version = held.reload.version
    fresh_version = fresh.reload.version
    outbox_before = Timekeeping::LocalOutboxEntry.count

    aborted = call.call(:abort, "invoice_id" => 501, "operation_id" => second)

    expect([aborted.status, aborted.body]).to eq([200, { "dropped" => 1 }])
