require "rails_helper"

RSpec.describe Timekeeping::LocalOwner, "reservation retries across a generation change" do
  # "A stale body generation on any of the five operations gives 409 stale_generation and writes nothing, including a retry whose earlier answer is stored"
  # "The generation check comes before replay, so a stale generation always gets 409 and changes nothing."
  it "a commit retried at the old generation after the generation moved answers stale_generation although its first answer is stored" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 30.0, bill_status: "unbilled"
    )
    service = described_class::Actor.service(
      name: "invoice-boundary", company_id: company.id, operations: %w[reservations.prepare reservations.commit]
    )
    call_owner = lambda do |operation, body, sent_generation|
      described_class.call(operation:, company_id: company.id, generation: sent_generation.to_s, actor: service,
                           params: { "body" => body.merge("generation" => sent_generation) })
    end
    operation_id = SecureRandom.uuid
    prepared = call_owner.call(:prepare, { "invoice_id" => 501, "operation_id" => operation_id,
                                           "disposition" => "active", "entries" => [entry.id] }, generation)
    expect(prepared.status).to eq(200)
    committed = call_owner.call(:commit, { "invoice_id" => 501, "operation_id" => operation_id }, generation)
    expect(committed.status).to eq(200)

    TimekeepingOwnership.current.update!(generation: generation + 1)
    tables = %w[reservations invoice_operations service_idempotency_receipts entry_audits entry_outbox_items entries]
    rows = -> { tables.index_with { |table| ActiveRecord::Base.connection.select_all("SELECT * FROM #{table} ORDER BY 1, 2").to_a } }
    before = rows.call

    stale = call_owner.call(:commit, { "invoice_id" => 501, "operation_id" => operation_id }, generation)

    # A replay of the stored commit answer here would defeat the rule: the fence must win over the receipt.
    expect([stale.status, stale.body]).to eq([409, { "reason" => "stale_generation" }])
    expect(rows.call).to eq(before)
  end
end
